  document.getElementById("procurementApprovalForm")?.addEventListener("submit", async (event) => { event.preventDefault();try{const active=state.procurementPackages.find((row)=>row.id===state.activeProcurementPackageId);if(!active)throw new Error("Select a procurement package.");const payload=values(event.currentTarget);const {data,error}=await db.rpc("hospital_submit_procurement_for_approval",{p_package_id:active.id,p_terms:payload.terms});if(error)throw error;await logAuditEvent("hospital_procurement_sent_for_client_approval",{moduleCode:MODULES.HOSPITAL_PROJECTS,entityType:"hospital_procurement_approvals",entityId:data?.id,afterData:data});showToast(`${data?.approval_number||"Procurement proposal"} is available in the client portal.`,TOAST_TYPES.SUCCESS);await loadView();render();}catch(error){showToast(error.message,TOAST_TYPES.ERROR);} });
