  document.getElementById("createPurchaseOrder")?.addEventListener("click", async () => { try{const active=state.procurementPackages.find((row)=>row.id===state.activeProcurementPackageId);if(!active)throw new Error("Select a procurement package.");const {data,error}=await db.rpc("hospital_create_purchase_order",{p_package_id:active.id,p_po_date:new Date().toISOString().slice(0,10),p_terms:null});if(error)throw error;await logAuditEvent("hospital_purchase_order_created",{moduleCode:MODULES.HOSPITAL_PROJECTS,entityType:"hospital_purchase_orders",entityId:data?.id,afterData:data});await loadView();const po=state.purchaseOrders.find((row)=>row.package_id===active.id);if(po?.payload_snapshot)await downloadHospitalPurchaseOrder(po.payload_snapshot);showToast(`${data?.po_number||"Purchase order"} generated.`,TOAST_TYPES.SUCCESS);render();}catch(error){showToast(error.message,TOAST_TYPES.ERROR);} });
